const CHASE_GAP_DAYS = 2;
const URGENT_START_WINDOW_DAYS = 2;

const today = new Date().toISOString().slice(0, 10);

function dayDiff(fromIso, toIso) {
  const a = Date.parse(String(fromIso) + 'T00:00:00Z');
  const b = Date.parse(String(toIso) + 'T00:00:00Z');
  if (isNaN(a) || isNaN(b)) return null;
  return Math.round((b - a) / 86400000);
}

// Same single definition of OVERDUE used in "Assess Readiness per Hire" and
// "Build the Onboarding Report": not done, and past its due date. Blocked
// counts. Do not change it in one node only.
function isOverdue(t) {
  return String(t.status) !== 'done' && Number(t.days_to_due) < 0;
}

const byOwner = {};
for (const it of $('Expand the Checklist per Hire').all()) {
  const t = it.json || {};
  if (t.status === 'done') continue;
  const k = String(t.owner_team || 'Unassigned');
  if (!byOwner[k]) byOwner[k] = [];
  byOwner[k].push(t);
}

const out = [];

for (const team of Object.keys(byOwner)) {
  const tasks = byOwner[team];
  // A chase only counts if a message actually went out. "Stamp the Chase on
  // Each Task" records last_chase_result, and while the send step is a
  // disabled demo node that result is 'drafted_only_send_step_disabled'.
  // A draft nobody received must not silence tomorrow's digest — without
  // this test the guard suppresses real work on the strength of a send that
  // never happened. Rows with no result recorded (the seeded fixture) are
  // treated as genuine sends, so the cadence guard is still demonstrable.
  const chased = tasks.filter(function (t) {
    if (String(t.last_chase_result || 'sent') !== 'sent') return false;
    const since = t.last_chased_on ? dayDiff(t.last_chased_on, today) : null;
    return since !== null && since < CHASE_GAP_DAYS;
  });
  const dueNow = tasks.filter(function (t) { return Number(t.days_to_due) <= 3; });
  const overdue = tasks.filter(isOverdue);
  const overdueMandatory = overdue.filter(function (t) { return t.mandatory; });
  const blockers = tasks.filter(function (t) { return t.blocks_day_one; });

  // The cadence guard stops a team being mailed twice about the same list.
  // It must never outrank urgency: something already overdue, or a day-one item
  // for somebody starting inside URGENT_START_WINDOW_DAYS, is chased again today
  // however recently it was last chased. The guard only quiets routine nagging.
  const imminentDayOne = tasks.filter(function (t) {
    return t.blocks_day_one && Number(t.days_to_start) <= URGENT_START_WINDOW_DAYS;
  });
  const urgent = overdue.length > 0 || imminentDayOne.length > 0;
  const chasedRecently = chased.length === tasks.length && tasks.length > 0;
  const suppressed = chasedRecently && !urgent;
  const overridden = chasedRecently && urgent;
  const worthSending = overdue.length > 0 || dueNow.length > 0;

  let overrideReason = '';
  if (overridden) {
    overrideReason = 'Chased within the last ' + CHASE_GAP_DAYS + ' day(s), but ' +
      (overdue.length
        ? overdue.length + ' item(s) are already overdue' + (overdueMandatory.length ? ' and ' + overdueMandatory.length + ' of those are mandatory' : '')
        : imminentDayOne.length + ' day-one item(s) belong to someone starting within ' + URGENT_START_WINDOW_DAYS + ' day(s)') +
      ', so the cadence guard was overridden and ' + team + ' is being chased again.';
  }

  out.push({
    json: {
      owner_team: team,
      owner_email: String(tasks[0].owner_email || ''),
      task_count: tasks.length,
      overdue_count: overdue.length,
      overdue_mandatory_count: overdueMandatory.length,
      due_soon_count: dueNow.length,
      day_one_blocker_count: blockers.length,
      imminent_day_one_count: imminentDayOne.length,
      chased_recently_count: chased.length,
      hires_touched: Array.from(new Set(tasks.map(function (t) { return t.hire_name; }))).length,
      urgency: overdue.length ? 'overdue' : (dueNow.length ? 'due_soon' : 'ahead'),
      send_digest: worthSending && !suppressed,
      urgency_override: overridden,
      override_reason: overrideReason,
      suppressed_reason: suppressed ? ('Every outstanding task for ' + team + ' was already chased within the last ' + CHASE_GAP_DAYS + ' day(s), and none of them is overdue or needed for a day one inside ' + URGENT_START_WINDOW_DAYS + ' day(s).') : '',
      not_yet_due_reason: (!worthSending && !suppressed) ? ('Nothing with ' + team + ' is overdue or due within 3 days.') : '',
      lines: tasks.map(function (t) {
        return {
          task_key: t.task_key,
          hire: t.hire_name,
          starts: t.start_date,
          days_to_start: t.days_to_start,
          task: t.task_name,
          due: t.due_date,
          days_to_due: t.days_to_due,
          status: t.status,
          mandatory: t.mandatory,
          overdue: isOverdue(t),
          blocks_day_one: t.blocks_day_one,
          reason: t.blocked_reason
        };
      }).sort(function (a, b) { return a.days_to_due - b.days_to_due; }),
      assessed_on: today,
      execution_id: String($execution.id || 'manual')
    }
  });
}

out.sort(function (a, b) { return b.json.overdue_count - a.json.overdue_count; });
return out;

