const MINUTES_PER_MANUAL_TASK = 6;

const hires = $('Assess Readiness per Hire').all().map(function (i) { return i.json; });
const tasks = $('Expand the Checklist per Hire').all().map(function (i) { return i.json; });
const digests = $('One Digest per Owner Team').all().map(function (i) { return i.json; });

function count(list, fn) { return list.filter(fn).length; }

// Same single definition of OVERDUE used in "Assess Readiness per Hire" and
// "One Digest per Owner Team": not done, and past its due date. The per-team
// breakdown below used to skip blocked tasks while the run total counted them,
// which is how one morning produced IT 3 overdue and IT 2 overdue at once.
function isOverdue(t) {
  return String(t.status) !== 'done' && Number(t.days_to_due) < 0;
}

const byTeam = {};
for (const t of tasks) {
  const k = String(t.owner_team || 'Unassigned');
  if (!byTeam[k]) byTeam[k] = { team: k, total: 0, done: 0, open: 0, blocked: 0, overdue: 0 };
  byTeam[k].total = byTeam[k].total + 1;
  if (t.status === 'done') byTeam[k].done = byTeam[k].done + 1;
  else if (t.status === 'blocked') byTeam[k].blocked = byTeam[k].blocked + 1;
  else byTeam[k].open = byTeam[k].open + 1;
  if (isOverdue(t)) byTeam[k].overdue = byTeam[k].overdue + 1;
}
const teams = Object.keys(byTeam).map(function (k) {
  const r = byTeam[k];
  return {
    team: r.team,
    total: r.total,
    done: r.done,
    open: r.open,
    blocked: r.blocked,
    overdue: r.overdue,
    complete_pct: r.total ? Math.round((r.done / r.total) * 100) : 0
  };
}).sort(function (a, b) { return b.overdue - a.overdue; });

const created = count(tasks, function (t) { return t.is_new; });

// What was actually DRAFTED is the post-filter list, not the send_digest flag on
// the pre-filter node. What was actually SENT is whatever the mail node handed
// back. The mail node is disabled in this demo, so it hands back its own input
// with no Gmail id or threadId and the confirmed count is honestly zero.
let queued = [];
try {
  queued = $('Only Teams Worth Chasing').all().map(function (i) { return i.json; });
} catch (e) {
  queued = [];
}

let mailConfirmed = 0;
try {
  for (const m of $('Email the Owning Team').all()) {
    const j = m.json || {};
    if (j.threadId || j.messageId || (j.id && j.labelIds)) mailConfirmed = mailConfirmed + 1;
  }
} catch (e) {
  mailConfirmed = 0;
}

let stamped = 0;
try {
  stamped = $('Stamp the Chase on Each Task').all().length;
} catch (e) {
  stamped = 0;
}

// Berapa yang BENAR-BENAR tertulis, bukan berapa yang disiapkan. 'Stamp the
// Chase' cuma menyusun barisnya; yang menentukan adalah baris yang
// dikembalikan tabel. Menghitung dari node penyusun berarti melaporkan niat
// sebagai perbuatan - persis kesalahan yang sedang dibersihkan di sini.
let chaseWritten = 0;
try {
  for (const r of $('Record the Chase').all()) {
    const j = r.json || {};
    if (j.id !== undefined && j.id !== null && j.updatedAt) chaseWritten = chaseWritten + 1;
  }
} catch (e) {
  chaseWritten = 0;
}

const drafted = queued.length;
const suppressedCount = digests.length - drafted;
const overridden = count(digests, function (d) { return d.urgency_override; });

const sendSummary = mailConfirmed > 0
  ? (mailConfirmed + ' team digest(s) went out, ' + suppressedCount + ' held back as already chased or not yet due.')
  : (drafted + ' team digest(s) were drafted and handed to the send step; the send step is switched off in this demo, so 0 actually went out. ' +
     suppressedCount + ' were held back as already chased or not yet due.');

return [{
  json: {
    run_id: String($execution.id || 'manual'),
    ran_on: new Date().toISOString().slice(0, 10),
    hires_in_flight: hires.length,
    ready: count(hires, function (h) { return h.outcome === 'ready'; }),
    on_track: count(hires, function (h) { return h.outcome === 'on_track'; }),
    at_risk: count(hires, function (h) { return h.outcome === 'at_risk'; }),
    blocked: count(hires, function (h) { return h.outcome === 'blocked'; }),
    tasks_total: tasks.length,
    tasks_done: count(tasks, function (t) { return t.status === 'done'; }),
    tasks_open: count(tasks, function (t) { return t.status !== 'done' && t.status !== 'blocked'; }),
    tasks_blocked: count(tasks, function (t) { return t.status === 'blocked'; }),
    tasks_overdue: count(tasks, isOverdue),
    tasks_created_this_run: created,
    digests_total: digests.length,
    digests_drafted: drafted,
    digests_sent: mailConfirmed,
    digests_suppressed: suppressedCount,
    digests_urgency_overridden: overridden,
    send_step_confirmed: mailConfirmed > 0,
    send_summary: sendSummary,
    chase_stamps_written: chaseWritten,
    chase_stamps_attempted: stamped,
    coordinator_minutes_saved: tasks.length * MINUTES_PER_MANUAL_TASK,
    by_team: teams,
    starting_soon: hires.filter(function (h) { return Number(h.days_to_start) <= 14; })
      .map(function (h) {
        return {
          name: h.hire_name,
          role: h.hire_role,
          starts: h.start_date,
          in_days: h.days_to_start,
          outcome: h.outcome,
          readiness: h.readiness_pct,
          headline: h.headline
        };
      }),
    needs_a_human: hires.filter(function (h) { return h.outcome === 'at_risk' || h.outcome === 'blocked'; })
      .map(function (h) {
        return {
          name: h.hire_name,
          manager: h.manager,
          starts: h.start_date,
          in_days: h.days_to_start,
          outcome: h.outcome,
          overdue: h.task_overdue,
          day_one_gaps: h.day_one_gaps,
          blocked: h.task_blocked,
          why: h.headline,
          outstanding: h.outstanding.map(function (o) { return o.task + ' (' + o.owner + ')'; }).join(', ')
        };
      })
  }
}];

