// The chase cadence guard in "One Digest per Owner Team" reads last_chased_on,
// but no node in this workflow ever wrote it. In production the column could
// only ever be empty, so the guard was permanently disarmed and only fired at
// all because the reset workflow seeded one row by hand.
//
// This node records the chase this run actually performed, for every task that
// appeared in a digest that reached the send step. The send step is a disabled
// demo node, so the result recorded says exactly that rather than claiming a
// message went out.
const today = new Date().toISOString().slice(0, 10);

const queued = $('Only Teams Worth Chasing').all().map(function (i) { return i.json; });

let confirmed = 0;
for (const it of $input.all()) {
  const j = it.json || {};
  if (j.threadId || j.messageId || (j.id && j.labelIds)) confirmed = confirmed + 1;
}

const result = confirmed > 0 ? 'sent' : 'drafted_only_send_step_disabled';

const out = [];
const seen = {};

for (const d of queued) {
  const lines = d.lines || [];
  for (const l of lines) {
    const key = String(l.task_key || '');
    if (!key) continue;
    if (seen[key]) continue;
    seen[key] = true;
    out.push({
      json: {
        task_key: key,
        owner_team: String(d.owner_team || ''),
        owner_email: String(d.owner_email || ''),
        hire: String(l.hire || ''),
        task: String(l.task || ''),
        last_chased_on: today,
        last_chase_result: result,
        urgency: String(d.urgency || ''),
        urgency_override: d.urgency_override === true,
        execution_id: String($execution.id || 'manual')
      }
    });
  }
}

return out;
